CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY INVOKER VIEW `v_data_quality_issues`  AS SELECT 'ORPHAN_NODE' AS `issue_code`, 'WARNING' AS `severity`, 'network_nodes' AS `entity`, `n`.`node_id` AS `entity_id`, `n`.`node_code` AS `entity_code`, `n`.`csc_id` AS `csc_id`, concat('Node "',`n`.`name`,'" is not referenced by any segment.') AS `description` FROM (`network_nodes` `n` join `v_node_degree` `g` on(`g`.`node_id` = `n`.`node_id`)) WHERE `g`.`segment_count` = 0 AND `n`.`status` = 'ACTIVE'union all select 'SWITCH_NODE_SINGLE_SEGMENT' AS `SWITCH_NODE_SINGLE_SEGMENT`,'WARNING' AS `WARNING`,'network_nodes' AS `network_nodes`,`n`.`node_id` AS `node_id`,`n`.`node_code` AS `node_code`,`n`.`csc_id` AS `csc_id`,concat('Node "',`n`.`name`,'" carries switchgear but touches only one segment. ','Confirm it is a line-end DDLO and set is_line_end.') AS `Name_exp_7` from (`network_nodes` `n` join `v_node_degree` `g` on(`g`.`node_id` = `n`.`node_id`)) where `g`.`segment_count` = 1 and `n`.`is_line_end` = 0 and `n`.`status` = 'ACTIVE' and exists(select 1 from ((`assets` `a` join `asset_types` `t` on(`t`.`asset_type_id` = `a`.`asset_type_id`)) join `asset_categories` `c` on(`c`.`category_id` = `t`.`category_id`)) where `a`.`node_id` = `n`.`node_id` and `c`.`category_code` = 'SWITCHGEAR' and `a`.`status` = 'ACTIVE' limit 1) union all select 'NODE_OWNER_NOT_ADJACENT' AS `NODE_OWNER_NOT_ADJACENT`,'ERROR' AS `ERROR`,'network_nodes' AS `network_nodes`,`n`.`node_id` AS `node_id`,`n`.`node_code` AS `node_code`,`n`.`csc_id` AS `csc_id`,concat('Owning depot of node "',`n`.`name`,'" does not own any adjacent segment.') AS `Name_exp_7` from (`network_nodes` `n` join `v_node_degree` `g` on(`g`.`node_id` = `n`.`node_id`)) where `g`.`segment_count` > 0 and `n`.`status` = 'ACTIVE' and !exists(select 1 from `v_node_segments` `vs` where `vs`.`node_id` = `n`.`node_id` and `vs`.`segment_csc_id` = `n`.`csc_id` limit 1) and !exists(select 1 from `node_shared_with` `sh` where `sh`.`node_id` = `n`.`node_id` and `sh`.`csc_id` = `n`.`csc_id` limit 1) union all select 'OWNERSHIP_OVERRIDE' AS `OWNERSHIP_OVERRIDE`,'INFO' AS `INFO`,'network_nodes' AS `network_nodes`,`n`.`node_id` AS `node_id`,`n`.`node_code` AS `node_code`,`n`.`csc_id` AS `csc_id`,concat('Ownership manually overridden: ',coalesce(`n`.`ownership_note`,'')) AS `Name_exp_7` from `network_nodes` `n` where `n`.`ownership_source` = 'MANUAL_OVERRIDE' and `n`.`status` = 'ACTIVE' union all select 'NODE_MISSING_COORDINATES' AS `NODE_MISSING_COORDINATES`,'WARNING' AS `WARNING`,'network_nodes' AS `network_nodes`,`n`.`node_id` AS `node_id`,`n`.`node_code` AS `node_code`,`n`.`csc_id` AS `csc_id`,concat('Node "',`n`.`name`,'" has no latitude/longitude.') AS `CONCAT('Node "', n.name, '" has no latitude/longitude.')` from `network_nodes` `n` where (`n`.`latitude` is null or `n`.`longitude` is null) and `n`.`status` = 'ACTIVE' union all select 'NODE_KIND_WITHOUT_ASSET' AS `NODE_KIND_WITHOUT_ASSET`,'ERROR' AS `ERROR`,'network_nodes' AS `network_nodes`,`n`.`node_id` AS `node_id`,`n`.`node_code` AS `node_code`,`n`.`csc_id` AS `csc_id`,concat('Node kind ',`n`.`node_kind`,' has no corresponding asset record, ','so it is not being counted anywhere.') AS `Name_exp_7` from `network_nodes` `n` where `n`.`status` = 'ACTIVE' and `n`.`node_kind` in ('SUBSTATION','GANTRY','GENERATION','BULK_SUPPLY') and !exists(select 1 from `assets` `a` where `a`.`node_id` = `n`.`node_id` and `a`.`status` = 'ACTIVE' limit 1) union all select 'SEGMENT_ZERO_LENGTH' AS `SEGMENT_ZERO_LENGTH`,'WARNING' AS `WARNING`,'segments' AS `segments`,`s`.`segment_id` AS `segment_id`,`s`.`segment_code` AS `segment_code`,`s`.`csc_id` AS `csc_id`,concat('Segment "',`s`.`segment_code`,'" has length 0.000 km.') AS `CONCAT('Segment "', s.segment_code, '" has length 0.000 km.')` from `segments` `s` where `s`.`length_km` <= 0 and `s`.`status` = 'ACTIVE' union all select 'SEGMENT_NO_CONDUCTOR' AS `SEGMENT_NO_CONDUCTOR`,'WARNING' AS `WARNING`,'segments' AS `segments`,`s`.`segment_id` AS `segment_id`,`s`.`segment_code` AS `segment_code`,`s`.`csc_id` AS `csc_id`,concat('Segment "',`s`.`segment_code`,'" has no conductor asset.') AS `CONCAT('Segment "', s.segment_code, '" has no conductor asset.')` from `segments` `s` where `s`.`status` = 'ACTIVE' and !exists(select 1 from ((`assets` `a` join `asset_types` `t` on(`t`.`asset_type_id` = `a`.`asset_type_id`)) join `asset_categories` `c` on(`c`.`category_id` = `t`.`category_id`)) where `a`.`segment_id` = `s`.`segment_id` and `c`.`category_code` = 'CONDUCTOR' and `a`.`status` = 'ACTIVE' limit 1) union all select 'CONDUCTOR_LENGTH_MISMATCH' AS `CONDUCTOR_LENGTH_MISMATCH`,'WARNING' AS `WARNING`,'segments' AS `segments`,`s`.`segment_id` AS `segment_id`,`s`.`segment_code` AS `segment_code`,`s`.`csc_id` AS `csc_id`,concat('Conductor total ',round(`x`.`cond_km`,3),' km against a span of ',`s`.`length_km`,' km. Check for a data entry error.') AS `Name_exp_7` from (`segments` `s` join (select `a`.`segment_id` AS `segment_id`,sum(`a`.`quantity`) AS `cond_km` from ((`assets` `a` join `asset_types` `t` on(`t`.`asset_type_id` = `a`.`asset_type_id`)) join `asset_categories` `c` on(`c`.`category_id` = `t`.`category_id`)) where `c`.`category_code` = 'CONDUCTOR' and `a`.`status` = 'ACTIVE' group by `a`.`segment_id`) `x` on(`x`.`segment_id` = `s`.`segment_id`)) where `s`.`status` = 'ACTIVE' and `s`.`length_km` > 0 and (`x`.`cond_km` < `s`.`length_km` * 0.8 or `x`.`cond_km` > `s`.`length_km` * 2.4) union all select 'REDUNDANT_SHARE' AS `REDUNDANT_SHARE`,'INFO' AS `INFO`,'node_shared_with' AS `node_shared_with`,`n`.`node_id` AS `node_id`,`n`.`node_code` AS `node_code`,`n`.`csc_id` AS `csc_id`,'Owning depot is also listed in node_shared_with.' AS `Owning depot is also listed in node_shared_with.` from (`network_nodes` `n` join `node_shared_with` `sh` on(`sh`.`node_id` = `n`.`node_id` and `sh`.`csc_id` = `n`.`csc_id`))  ;

