--
-- Structure for view `v_depot_dashboard`
--
DROP TABLE IF EXISTS `v_depot_dashboard`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY INVOKER VIEW `v_depot_dashboard`  AS SELECT `d`.`csc_id` AS `csc_id`, `d`.`csc_code` AS `csc_code`, `d`.`csc_name` AS `csc_name`, `d`.`page_no` AS `page_no`, `ar`.`area_id` AS `area_id`, `ar`.`area_no` AS `area_no`, `ar`.`area_name` AS `area_name`, `p`.`province_id` AS `province_id`, `p`.`province_name` AS `province_name`, coalesce((select count(0) from `network_nodes` `n` where `n`.`csc_id` = `d`.`csc_id` and `n`.`status` = 'ACTIVE'),0) AS `node_count`, coalesce((select count(0) from `segments` `s` where `s`.`csc_id` = `d`.`csc_id` and `s`.`status` = 'ACTIVE'),0) AS `segment_count`, coalesce((select sum(`s`.`length_km`) from `segments` `s` where `s`.`csc_id` = `d`.`csc_id` and `s`.`status` = 'ACTIVE'),0) AS `network_km`, coalesce((select sum(`r`.`quantity`) from `v_asset_rollup` `r` where `r`.`csc_id` = `d`.`csc_id`),0) AS `asset_quantity`, coalesce((select count(0) from `v_transformer_rollup` `tr` where `tr`.`csc_id` = `d`.`csc_id`),0) AS `transformer_count`, coalesce((select sum(coalesce(`tr`.`capacity_kva`,0) * `tr`.`quantity`) from `v_transformer_rollup` `tr` where `tr`.`csc_id` = `d`.`csc_id`),0) AS `installed_kva` FROM ((`csc_depots` `d` join `areas` `ar` on(`ar`.`area_id` = `d`.`area_id`)) join `provinces` `p` on(`p`.`province_id` = `ar`.`province_id`)) WHERE `d`.`is_active` = 1 ;

-- --------------------------------------------------------

--
-- Structure for view `v_line_length_by_area`
--
DROP TABLE IF EXISTS `v_line_length_by_area`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_line_length_by_area`  AS SELECT `a`.`area_id` AS `area_id`, `a`.`area_code` AS `area_code`, `a`.`area_name` AS `area_name`, count(distinct `d`.`csc_id`) AS `csc_count`, count(`s`.`register_id`) AS `segment_count`, coalesce(sum(`s`.`is_split`),0) AS `crossing_count`, count(distinct `sr`.`feeder_id`) AS `feeder_count`, coalesce(sum(`s`.`length_km`),0) AS `total_km`, round(coalesce(avg(`s`.`length_km`),0),3) AS `mean_km`, coalesce(max(`s`.`length_km`),0) AS `longest_km` FROM (((`areas` `a` join `csc_depots` `d` on(`d`.`area_id` = `a`.`area_id`)) left join `v_segment_csc_share` `s` on(`s`.`csc_id` = `d`.`csc_id`)) left join `segment_register` `sr` on(`sr`.`register_id` = `s`.`register_id`)) GROUP BY `a`.`area_id`, `a`.`area_code`, `a`.`area_name` ;

-- --------------------------------------------------------

--
-- Structure for view `v_line_length_by_csc`
--
DROP TABLE IF EXISTS `v_line_length_by_csc`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_line_length_by_csc`  AS SELECT `d`.`csc_id` AS `csc_id`, `d`.`csc_code` AS `csc_code`, `d`.`csc_name` AS `csc_name`, `a`.`area_id` AS `area_id`, `a`.`area_name` AS `area_name`, count(`s`.`register_id`) AS `segment_count`, sum(`s`.`is_split`) AS `crossing_count`, coalesce(sum(`s`.`length_km`),0) AS `total_km`, round(coalesce(avg(`s`.`length_km`),0),3) AS `mean_km`, coalesce(max(`s`.`length_km`),0) AS `longest_km` FROM ((`v_segment_csc_share` `s` join `csc_depots` `d` on(`d`.`csc_id` = `s`.`csc_id`)) join `areas` `a` on(`a`.`area_id` = `d`.`area_id`)) GROUP BY `d`.`csc_id`, `d`.`csc_code`, `d`.`csc_name`, `a`.`area_id`, `a`.`area_name` ;

-- --------------------------------------------------------

--
-- Structure for view `v_line_length_by_feeder`
--
DROP TABLE IF EXISTS `v_line_length_by_feeder`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY INVOKER VIEW `v_line_length_by_feeder`  AS SELECT `f`.`feeder_id` AS `feeder_id`, `f`.`feeder_code` AS `feeder_code`, `f`.`feeder_name` AS `feeder_name`, `f`.`origin_csc_id` AS `origin_csc_id`, `f`.`external_source` AS `external_source`, count(distinct `sr`.`csc_id`) AS `depots_crossed`, count(0) AS `segment_count`, sum(`sr`.`length_km`) AS `total_km` FROM (`segment_register` `sr` join `feeders` `f` on(`f`.`feeder_id` = `sr`.`feeder_id`)) WHERE `sr`.`status` = 'ACTIVE' GROUP BY `f`.`feeder_id`, `f`.`feeder_code`, `f`.`feeder_name`, `f`.`origin_csc_id`, `f`.`external_source` ;

-- --------------------------------------------------------

--
-- Structure for view `v_node_degree`
--
DROP TABLE IF EXISTS `v_node_degree`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY INVOKER VIEW `v_node_degree`  AS SELECT `n`.`node_id` AS `node_id`, `n`.`node_code` AS `node_code`, `n`.`csc_id` AS `csc_id`, count(`s`.`segment_id`) AS `segment_count`, sum(case when `s`.`to_node_id` = `n`.`node_id` then 1 else 0 end) AS `upstream_count`, sum(case when `s`.`from_node_id` = `n`.`node_id` then 1 else 0 end) AS `downstream_count` FROM (`network_nodes` `n` left join `segments` `s` on((`n`.`node_id` = `s`.`from_node_id` or `n`.`node_id` = `s`.`to_node_id`) and `s`.`status` <> 'RETIRED')) GROUP BY `n`.`node_id`, `n`.`node_code`, `n`.`csc_id` ;

-- --------------------------------------------------------

--
-- Structure for view `v_node_segments`
--
DROP TABLE IF EXISTS `v_node_segments`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY INVOKER VIEW `v_node_segments`  AS SELECT `n`.`node_id` AS `node_id`, `n`.`node_code` AS `node_code`, `n`.`name` AS `node_name`, `n`.`csc_id` AS `node_csc_id`, `s`.`segment_id` AS `segment_id`, `s`.`segment_code` AS `segment_code`, `s`.`feeder_id` AS `feeder_id`, `s`.`csc_id` AS `segment_csc_id`, `s`.`length_km` AS `length_km`, `s`.`voltage_level` AS `voltage_level`, `s`.`status` AS `segment_status`, CASE WHEN `s`.`to_node_id` = `n`.`node_id` THEN 'UPSTREAM_OF_NODE' ELSE 'DOWNSTREAM_OF_NODE' END AS `relation`, CASE WHEN `s`.`to_node_id` = `n`.`node_id` THEN `s`.`from_node_id` ELSE `s`.`to_node_id` END AS `other_node_id` FROM (`network_nodes` `n` join `segments` `s` on(`n`.`node_id` = `s`.`from_node_id` or `n`.`node_id` = `s`.`to_node_id`)) ;

-- --------------------------------------------------------

--
-- Structure for view `v_pending_users`
--
DROP TABLE IF EXISTS `v_pending_users`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_pending_users`  AS SELECT `u`.`user_id` AS `user_id`, `u`.`username` AS `username`, `u`.`employee_no` AS `employee_no`, `u`.`full_name` AS `full_name`, `u`.`designation` AS `designation`, `u`.`email` AS `email`, `u`.`phone` AS `phone`, `u`.`created_at` AS `created_at`, `r`.`role_code` AS `role_code`, `r`.`role_name` AS `role_name`, `rq`.`role_code` AS `requested_role_code`, `rq`.`role_name` AS `requested_role_name`, `a`.`area_id` AS `area_id`, `a`.`area_name` AS `area_name`, `d`.`csc_id` AS `csc_id`, `d`.`csc_code` AS `csc_code`, `d`.`csc_name` AS `csc_name` FROM ((((`users` `u` join `roles` `r` on(`r`.`role_id` = `u`.`role_id`)) left join `roles` `rq` on(`rq`.`role_id` = `u`.`requested_role_id`)) left join `areas` `a` on(`a`.`area_id` = `u`.`area_id`)) left join `csc_depots` `d` on(`d`.`csc_id` = `u`.`csc_id`)) WHERE `u`.`registration_source` = 'SELF_REGISTERED' AND `u`.`scope_assigned` = 0 AND `u`.`is_active` = 1 ;

