--
-- Structure for view `v_search_index`
--
DROP TABLE IF EXISTS `v_search_index`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_search_index`  AS SELECT 'transformer' FROM (((`transformers` `tx` join `csc_depots` `d` on(`d`.`csc_id` = `tx`.`csc_id`)) join `areas` `ar` on(`ar`.`area_id` = `d`.`area_id`)) left join `asset_types` `t` on(`t`.`asset_type_id` = `tx`.`asset_type_id`))union all select 'switchgear' collate utf8mb4_unicode_ci AS `'switchgear' COLLATE utf8mb4_unicode_ci`,`sw`.`switchgear_id` AS `switchgear_id`,`sw`.`switch_code` collate utf8mb4_unicode_ci AS `sw.switch_code COLLATE utf8mb4_unicode_ci`,coalesce(nullif(`sw`.`switch_name`,''),`sw`.`nearest_substation`,`sw`.`switch_code`) collate utf8mb4_unicode_ci AS `Name_exp_4`,coalesce(`t`.`type_name`,'Switchgear') collate utf8mb4_unicode_ci AS `COALESCE(t.type_name, 'Switchgear') COLLATE utf8mb4_unicode_ci`,concat(`d`.`csc_name`,' CSC · ',`ar`.`area_name`) collate utf8mb4_unicode_ci AS `Name_exp_6`,`d`.`csc_id` AS `csc_id`,`ar`.`area_id` AS `area_id`,`sw`.`status` collate utf8mb4_unicode_ci AS `sw.status COLLATE utf8mb4_unicode_ci`,lcase(concat_ws(' ',`sw`.`switch_code`,`sw`.`switch_name`,`sw`.`nearest_substation`,`t`.`type_name`,`d`.`csc_name`,`d`.`csc_code`,`ar`.`area_name`,`ar`.`area_code`)) collate utf8mb4_unicode_ci AS `Name_exp_10` from (((`switchgear` `sw` join `csc_depots` `d` on(`d`.`csc_id` = `sw`.`csc_id`)) join `areas` `ar` on(`ar`.`area_id` = `d`.`area_id`)) left join `asset_types` `t` on(`t`.`asset_type_id` = `sw`.`asset_type_id`)) union all select 'segment' collate utf8mb4_unicode_ci AS `'segment' COLLATE utf8mb4_unicode_ci`,`sr`.`register_id` AS `register_id`,`sr`.`segment_code` collate utf8mb4_unicode_ci AS `sr.segment_code COLLATE utf8mb4_unicode_ci`,concat(`sr`.`segment_code`,' — ',format(`sr`.`length_km`,3),' km') collate utf8mb4_unicode_ci AS `Name_exp_4`,concat_ws(' · ',`sr`.`voltage_level`,`f`.`feeder_code`) collate utf8mb4_unicode_ci AS `Name_exp_5`,concat(`d`.`csc_name`,' CSC · ',`ar`.`area_name`) collate utf8mb4_unicode_ci AS `Name_exp_6`,`d`.`csc_id` AS `csc_id`,`ar`.`area_id` AS `area_id`,`sr`.`status` collate utf8mb4_unicode_ci AS `sr.status COLLATE utf8mb4_unicode_ci`,lcase(concat_ws(' ',`sr`.`segment_code`,`sr`.`voltage_level`,`f`.`feeder_code`,`f`.`feeder_name`,`d`.`csc_name`,`d`.`csc_code`,`ar`.`area_name`,`ar`.`area_code`)) collate utf8mb4_unicode_ci AS `Name_exp_10` from (((`segment_register` `sr` join `csc_depots` `d` on(`d`.`csc_id` = `sr`.`csc_id`)) join `areas` `ar` on(`ar`.`area_id` = `d`.`area_id`)) left join `feeders` `f` on(`f`.`feeder_id` = `sr`.`feeder_id`)) union all select 'csc' collate utf8mb4_unicode_ci AS `'csc' COLLATE utf8mb4_unicode_ci`,`d`.`csc_id` AS `csc_id`,`d`.`csc_code` collate utf8mb4_unicode_ci AS `d.csc_code COLLATE utf8mb4_unicode_ci`,`d`.`csc_name` collate utf8mb4_unicode_ci AS `d.csc_name COLLATE utf8mb4_unicode_ci`,concat(`d`.`depot_type`,' in ',`ar`.`area_name`,' area') collate utf8mb4_unicode_ci AS `Name_exp_5`,`ar`.`area_name` collate utf8mb4_unicode_ci AS `ar.area_name COLLATE utf8mb4_unicode_ci`,`d`.`csc_id` AS `csc_id`,`ar`.`area_id` AS `area_id`,if(`d`.`is_active`,'ACTIVE','RETIRED') collate utf8mb4_unicode_ci AS `IF(d.is_active, 'ACTIVE', 'RETIRED') COLLATE utf8mb4_unicode_ci`,lcase(concat_ws(' ',`d`.`csc_code`,`d`.`csc_name`,`ar`.`area_name`,`ar`.`area_code`)) collate utf8mb4_unicode_ci AS `Name_exp_10` from (`csc_depots` `d` join `areas` `ar` on(`ar`.`area_id` = `d`.`area_id`)) union all select 'area' collate utf8mb4_unicode_ci AS `'area' COLLATE utf8mb4_unicode_ci`,`ar`.`area_id` AS `area_id`,`ar`.`area_code` collate utf8mb4_unicode_ci AS `ar.area_code COLLATE utf8mb4_unicode_ci`,`ar`.`area_name` collate utf8mb4_unicode_ci AS `ar.area_name COLLATE utf8mb4_unicode_ci`,concat('Area ',`ar`.`area_no`,' · ',`p`.`province_name`,' Province') collate utf8mb4_unicode_ci AS `Name_exp_5`,`p`.`province_name` collate utf8mb4_unicode_ci AS `p.province_name COLLATE utf8mb4_unicode_ci`,NULL AS `NULL`,`ar`.`area_id` AS `area_id`,if(`ar`.`is_active`,'ACTIVE','RETIRED') collate utf8mb4_unicode_ci AS `IF(ar.is_active, 'ACTIVE', 'RETIRED') COLLATE utf8mb4_unicode_ci`,lcase(concat_ws(' ',`ar`.`area_code`,`ar`.`area_name`,`p`.`province_name`)) collate utf8mb4_unicode_ci AS `Name_exp_10` from (`areas` `ar` join `provinces` `p` on(`p`.`province_id` = `ar`.`province_id`)) union all select 'feeder' collate utf8mb4_unicode_ci AS `'feeder' COLLATE utf8mb4_unicode_ci`,`f`.`feeder_id` AS `feeder_id`,`f`.`feeder_code` collate utf8mb4_unicode_ci AS `f.feeder_code COLLATE utf8mb4_unicode_ci`,`f`.`feeder_name` collate utf8mb4_unicode_ci AS `f.feeder_name COLLATE utf8mb4_unicode_ci`,concat_ws(' · ',`f`.`voltage_level`,`f`.`source_name`) collate utf8mb4_unicode_ci AS `Name_exp_5`,coalesce(concat(`d`.`csc_name`,' CSC'),'Origin not recorded') collate utf8mb4_unicode_ci AS `Name_exp_6`,`f`.`origin_csc_id` AS `origin_csc_id`,`d`.`area_id` AS `area_id`,`f`.`status` collate utf8mb4_unicode_ci AS `f.status COLLATE utf8mb4_unicode_ci`,lcase(concat_ws(' ',`f`.`feeder_code`,`f`.`feeder_name`,`f`.`source_name`,`f`.`voltage_level`,`d`.`csc_name`,`d`.`csc_code`)) collate utf8mb4_unicode_ci AS `Name_exp_10` from (`feeders` `f` left join `csc_depots` `d` on(`d`.`csc_id` = `f`.`origin_csc_id`)) union all select 'asset' collate utf8mb4_unicode_ci AS `'asset' COLLATE utf8mb4_unicode_ci`,`r`.`source_id` AS `source_id`,`r`.`asset_code` collate utf8mb4_unicode_ci AS `r.asset_code COLLATE utf8mb4_unicode_ci`,`r`.`type_name` collate utf8mb4_unicode_ci AS `r.type_name COLLATE utf8mb4_unicode_ci`,concat(format(`r`.`quantity`,if(`r`.`unit_of_measure` = 'km',3,0)),' ',`r`.`unit_of_measure`,' · ',`r`.`category_name`) collate utf8mb4_unicode_ci AS `Name_exp_5`,concat(`r`.`csc_name`,' CSC · ',`r`.`area_name`) collate utf8mb4_unicode_ci AS `Name_exp_6`,`r`.`csc_id` AS `csc_id`,`r`.`area_id` AS `area_id`,'ACTIVE' collate utf8mb4_unicode_ci AS `'ACTIVE' COLLATE utf8mb4_unicode_ci`,lcase(concat_ws(' ',`r`.`asset_code`,`r`.`type_name`,`r`.`category_name`,`r`.`attached_ref`,`r`.`csc_name`,`r`.`csc_code`,`r`.`area_name`,`r`.`area_code`)) collate utf8mb4_unicode_ci AS `Name_exp_10` from `v_asset_register` `r` where `r`.`source` collate utf8mb4_unicode_ci = 'assets'  ;

